/* --------------------------------------------------------------------------------------------------
   5) dbo.RegisterDatabaseBackup — تسجيل النسخ الاحتياطية قبل الإغلاق السنوي.
   -------------------------------------------------------------------------------------------------- */
CREATE   PROCEDURE [dbo].[RegisterDatabaseBackup]
    @BackupFile  NVARCHAR(500),
    @BackupType  NVARCHAR(50),
    @AcademicYear NVARCHAR(20) = NULL,
    @UserID       INT = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF NULLIF(LTRIM(RTRIM(@BackupFile)), N'') IS NULL
        THROW 51103, N'ملف النسخة الاحتياطية غير صالح.', 1;

    INSERT dbo.DatabaseBackupHistory (BackupFile, BackupType, AcademicYear, CreatedByUserID, IsVerified)
    VALUES (@BackupFile, @BackupType, NULLIF(LTRIM(RTRIM(@AcademicYear)), N''), @UserID, 1);

    SELECT CAST(SCOPE_IDENTITY() AS BIGINT) AS BackupHistoryID;
END;

GO
/****** Object:  StoredProcedure [dbo].[SetActiveAcademicYear]    Script Date: 8/31/2026 7:21:21 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/* --------------------------------------------------------------------------------------------------
   4) dbo.SetActiveAcademicYear — تعيين العام الدراسي النشط.
   -------------------------------------------------------------------------------------------------- */
CREATE   PROCEDURE [dbo].[SetActiveAcademicYear]
    @AcademicYear NVARCHAR(20),
    @UserID INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @AcademicYear = REPLACE(NULLIF(LTRIM(RTRIM(@AcademicYear)), N''), N'-', N'/');

    IF @AcademicYear IS NULL
        THROW 51101, N'العام الدراسي النشط غير صالح.', 1;

    IF EXISTS (SELECT 1 FROM dbo.AnnualClosings WHERE AcademicYear = @AcademicYear AND ClosingStatus IN (N'مغلق', N'مؤرشف'))
        THROW 51102, N'لا يمكن جعل عام مغلق هو العام النشط.', 1;

    BEGIN TRANSACTION;

    IF EXISTS (SELECT 1 FROM dbo.SystemAcademicSettings)
        UPDATE dbo.SystemAcademicSettings
           SET ActiveAcademicYear = @AcademicYear,
               UpdatedByUserID = @UserID,
               UpdatedAt = GETDATE();
    ELSE
        INSERT dbo.SystemAcademicSettings (ActiveAcademicYear, UpdatedByUserID)
        VALUES (@AcademicYear, @UserID);

    COMMIT TRANSACTION;

    SELECT @AcademicYear AS ActiveAcademicYear;
END;

GO
/****** Object:  StoredProcedure [dbo].[VerifyAnnualClosing]    Script Date: 8/31/2026 7:21:21 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[VerifyAnnualClosing]
    @AcademicYear NVARCHAR(20)
AS
BEGIN
    SET NOCOUNT ON;
    SET @AcademicYear = REPLACE(LTRIM(RTRIM(@AcademicYear)), N'-', N'/');
    IF NULLIF(@AcademicYear, N'') IS NULL
        THROW 51020, N'يجب تحديد العام الدراسي قبل الفحص.', 1;

    DECLARE @Issues TABLE
    (
        CheckCode NVARCHAR(80) NOT NULL,
        CheckName NVARCHAR(200) NOT NULL,
        IssueCount INT NOT NULL,
        Severity NVARCHAR(20) NOT NULL,
        Details NVARCHAR(500) NULL
    );

    IF OBJECT_ID(N'dbo.StudentClasses', N'U') IS NOT NULL
    BEGIN
        INSERT @Issues VALUES
        (N'STUDENT_ASSIGNMENT_DUPLICATE', N'توزيع الطالب المكرر في العام',
         ISNULL((SELECT COUNT(*) FROM (SELECT StudentID FROM dbo.StudentClasses WHERE REPLACE(ISNULL(AcademicYear,N''),N'-',N'/')=@AcademicYear GROUP BY StudentID HAVING COUNT(*)>1) x),0), N'حرج', N'يجب أن يكون لكل طالب توزيع فعّال واحد في العام.'),
        (N'STUDENT_ASSIGNMENT_ORPHAN', N'توزيع يشير إلى طالب غير موجود',
         ISNULL((SELECT COUNT(*) FROM dbo.StudentClasses sc LEFT JOIN dbo.Students s ON s.StudentID=sc.StudentID WHERE REPLACE(ISNULL(sc.AcademicYear,N''),N'-',N'/')=@AcademicYear AND s.StudentID IS NULL),0), N'حرج', N'سجل توزيع بلا طالب.'),
        (N'STUDENT_ASSIGNMENT_ORPHAN_CLASS', N'توزيع يشير إلى صف غير موجود',
         ISNULL((SELECT COUNT(*) FROM dbo.StudentClasses sc LEFT JOIN dbo.Classes c ON c.ClassID=sc.ClassID WHERE REPLACE(ISNULL(sc.AcademicYear,N''),N'-',N'/')=@AcademicYear AND c.ClassID IS NULL),0), N'حرج', N'سجل توزيع بلا صف.');
    END;

    IF OBJECT_ID(N'dbo.Enrollments', N'U') IS NOT NULL
    BEGIN
        INSERT @Issues VALUES
        (N'ENROLLMENT_ORPHAN', N'تسجيل يشير إلى طالب غير موجود',
         ISNULL((SELECT COUNT(*) FROM dbo.Enrollments e LEFT JOIN dbo.Students s ON s.StudentID=e.StudentID WHERE REPLACE(ISNULL(e.AcademicYear,N''),N'-',N'/')=@AcademicYear AND s.StudentID IS NULL),0), N'حرج', N'سجل تسجيل بلا طالب.'),
        (N'ENROLLMENT_DUPLICATE', N'التسجيل المكرر للطالب في العام',
         ISNULL((SELECT COUNT(*) FROM (SELECT StudentID FROM dbo.Enrollments WHERE REPLACE(ISNULL(AcademicYear,N''),N'-',N'/')=@AcademicYear GROUP BY StudentID HAVING COUNT(*)>1) x),0), N'حرج', N'يجب مراجعة التسجيلات المكررة قبل الإغلاق.');
    END;

    IF OBJECT_ID(N'dbo.Fees', N'U') IS NOT NULL
    BEGIN
        INSERT @Issues VALUES
        (N'FEE_ORPHAN', N'رسم يشير إلى طالب غير موجود',
         ISNULL((SELECT COUNT(*) FROM dbo.Fees f LEFT JOIN dbo.Students s ON s.StudentID=f.StudentID WHERE REPLACE(ISNULL(f.AcademicYear,N''),N'-',N'/')=@AcademicYear AND s.StudentID IS NULL),0), N'حرج', N'الرسم بلا طالب.'),
        (N'FEE_NEGATIVE', N'مبلغ رسم سالب أو صافي غير صحيح',
         ISNULL((SELECT COUNT(*) FROM dbo.Fees WHERE REPLACE(ISNULL(AcademicYear,N''),N'-',N'/')=@AcademicYear AND (ISNULL(TotalAmount,0)<0 OR ISNULL(PaidAmount,0)<0 OR ISNULL(RemainingAmount,0)<0 OR ISNULL(PaidAmount,0)>ISNULL(NetAmount,ISNULL(TotalAmount,0)))),0), N'حرج', N'مراجعة المبالغ والدفعات.');
    END;

    IF OBJECT_ID(N'dbo.Vouchers', N'U') IS NOT NULL
    BEGIN
        INSERT @Issues VALUES
        (N'VOUCHER_DUPLICATE_NUMBER', N'رقم السند المكرر',
         ISNULL((SELECT COUNT(*) FROM (SELECT VoucherNumber FROM dbo.Vouchers WHERE NULLIF(LTRIM(RTRIM(VoucherNumber)),N'') IS NOT NULL GROUP BY VoucherNumber HAVING COUNT(*)>1) x),0), N'حرج', N'رقم السند يجب أن يكون فريداً.');
    END;

    SELECT CheckCode, CheckName, IssueCount, Severity, Details,
           CASE WHEN IssueCount=0 THEN N'سليم' ELSE N'يحتاج معالجة' END AS Result
    FROM @Issues ORDER BY CASE Severity WHEN N'حرج' THEN 1 ELSE 2 END, CheckCode;
END;
GO

/*
   Operational data seeding — merged from SchoolDB_OperationalData.sql
   Add-only reference/operational seeding. No UPDATE, DELETE, TRUNCATE or MERGE.
   Academic year 2025/2026 removed — only 2026/2027 active year included.
   Demo data section removed.
*/
SET NOCOUNT ON;
SET XACT_ABORT ON;
GO

BEGIN TRY
    BEGIN TRANSACTION;

    INSERT dbo.AcademicYears (AcademicYear, StartDate, EndDate, IsActive)
    SELECT v.AcademicYear, v.StartDate, v.EndDate, v.IsActive
    FROM (VALUES
        (N'2026/2027', CONVERT(date,'2026-09-01'), CONVERT(date,'2027-06-30'), CAST(1 AS bit))
    ) v(AcademicYear, StartDate, EndDate, IsActive)
    WHERE NOT EXISTS (SELECT 1 FROM dbo.AcademicYears y WHERE y.AcademicYear = v.AcademicYear);

    INSERT dbo.Stages (StageCode, StageName, StageOrder, IsActive)
    SELECT v.StageCode, v.StageName, v.StageOrder, 1
    FROM (VALUES
        (N'BASIC', N'المرحلة الأساسية', 1),
        (N'PREP', N'المرحلة الإعدادية', 2),
        (N'SEC', N'المرحلة الثانوية', 3)
    ) v(StageCode, StageName, StageOrder)
    WHERE NOT EXISTS (SELECT 1 FROM dbo.Stages s WHERE s.StageCode = v.StageCode);

    INSERT dbo.AcademicTerms (TermCode, TermName, TermOrder, IsActive)
    SELECT v.TermCode, v.TermName, v.TermOrder, 1
    FROM (VALUES
        (N'TERM-1', N'الفصل الدراسي الأول', 1),
        (N'TERM-2', N'الفصل الدراسي الثاني', 2)
    ) v(TermCode, TermName, TermOrder)
    WHERE NOT EXISTS (SELECT 1 FROM dbo.AcademicTerms t WHERE t.TermCode = v.TermCode);

    INSERT dbo.Classes (ClassCode, ClassName, StageName, StageID, GradeOrder, IsActive, Notes)
    SELECT v.ClassCode, v.ClassName, s.StageName, s.StageID, v.GradeOrder, 1, N'صف مرجعي أساسي للنظام'
    FROM (VALUES
        (N'BASIC-01',N'الأول الأساسي',1,N'BASIC'),
        (N'BASIC-02',N'الثاني الأساسي',2,N'BASIC'),
        (N'BASIC-03',N'الثالث الأساسي',3,N'BASIC'),
        (N'BASIC-04',N'الرابع الأساسي',4,N'BASIC'),
        (N'BASIC-05',N'الخامس الأساسي',5,N'BASIC'),
        (N'BASIC-06',N'السادس الأساسي',6,N'BASIC'),
        (N'PREP-01',N'الأول الإعدادي',7,N'PREP'),
        (N'PREP-02',N'الثاني الإعدادي',8,N'PREP'),
        (N'PREP-03',N'الثالث الإعدادي',9,N'PREP'),
        (N'SEC-01',N'الأول الثانوي',10,N'SEC'),
        (N'SEC-02',N'الثاني الثانوي',11,N'SEC'),
        (N'SEC-03',N'الثالث الثانوي',12,N'SEC')
    ) v(ClassCode, ClassName, GradeOrder, StageCode)
    INNER JOIN dbo.Stages s ON s.StageCode = v.StageCode
    WHERE NOT EXISTS (SELECT 1 FROM dbo.Classes c WHERE c.ClassCode = v.ClassCode OR c.ClassName = v.ClassName);

    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;
GO


BEGIN TRY
    BEGIN TRANSACTION;
    DECLARE @SubjectRows TABLE (Suffix NVARCHAR(10) NOT NULL, SubjectName NVARCHAR(100) NOT NULL, StageCode NVARCHAR(30) NOT NULL);
    INSERT @SubjectRows(Suffix, SubjectName, StageCode)
    VALUES
      (N'QUR',N'القرآن الكريم',N'BASIC'),(N'ISL',N'التربية الإسلامية',N'BASIC'),
      (N'AR',N'اللغة العربية',N'BASIC'),(N'MA',N'الرياضيات',N'BASIC'),(N'SCI',N'العلوم',N'BASIC'),
      (N'SOC',N'التربية الاجتماعية',N'BASIC'),(N'EN',N'اللغة الإنجليزية',N'BASIC'),
      (N'CS',N'الحاسوب',N'BASIC'),(N'ART',N'التربية الفنية',N'BASIC'),(N'PE',N'التربية البدنية',N'BASIC'),
      (N'QUR',N'القرآن الكريم',N'PREP'),(N'ISL',N'التربية الإسلامية',N'PREP'),
      (N'AR',N'اللغة العربية',N'PREP'),(N'MA',N'الرياضيات',N'PREP'),(N'SCI',N'العلوم',N'PREP'),
      (N'SOC',N'الدراسات الاجتماعية',N'PREP'),(N'EN',N'اللغة الإنجليزية',N'PREP'),
      (N'CS',N'الحاسوب',N'PREP'),(N'ART',N'التربية الفنية',N'PREP'),(N'PE',N'التربية البدنية',N'PREP'),
      (N'ISL',N'التربية الإسلامية',N'SEC'),(N'AR',N'اللغة العربية',N'SEC'),
      (N'EN',N'اللغة الإنجليزية',N'SEC'),(N'MA',N'الرياضيات',N'SEC'),(N'PH',N'الفيزياء',N'SEC'),
      (N'CH',N'الكيمياء',N'SEC'),(N'BI',N'الأحياء',N'SEC'),(N'HIS',N'التاريخ',N'SEC'),
      (N'GEO',N'الجغرافيا',N'SEC'),(N'CS',N'الحاسوب',N'SEC'),(N'PE',N'التربية البدنية',N'SEC');

    INSERT dbo.Subjects (SubjectCode, SubjectName, ClassID, MaxDegree, PassDegree, IsActive, Notes)
    SELECT c.ClassCode + N'-' + x.Suffix, x.SubjectName, c.ClassID, 100, 50, 1, N'مادة مرجعية مرتبطة بالصف'
    FROM dbo.Classes c
    INNER JOIN dbo.Stages st ON st.StageID = c.StageID
    INNER JOIN @SubjectRows x ON x.StageCode = st.StageCode
    WHERE c.IsActive = 1
      AND NOT EXISTS
      (
          SELECT 1 FROM dbo.Subjects s
          WHERE s.ClassID = c.ClassID AND (s.SubjectCode = c.ClassCode + N'-' + x.Suffix OR s.SubjectName = x.SubjectName)
      );

    INSERT dbo.ClassSubjects (ClassID, SubjectID)
    SELECT s.ClassID, s.SubjectID
    FROM dbo.Subjects s
    WHERE s.ClassID IS NOT NULL AND ISNULL(s.IsActive, 1) = 1
      AND NOT EXISTS (SELECT 1 FROM dbo.ClassSubjects cs WHERE cs.ClassID = s.ClassID AND cs.SubjectID = s.SubjectID);

    INSERT dbo.ClassSubjectTerms (ClassSubjectID, TermID, IsActive)
    SELECT cs.ClassSubjectID, t.TermID, 1
    FROM dbo.ClassSubjects cs
    CROSS JOIN dbo.AcademicTerms t
    WHERE ISNULL(cs.IsActive, 1) = 1 AND ISNULL(t.IsActive, 1) = 1
      AND NOT EXISTS (SELECT 1 FROM dbo.ClassSubjectTerms cst WHERE cst.ClassSubjectID = cs.ClassSubjectID AND cst.TermID = t.TermID);

    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;
GO


INSERT dbo.SchoolSections (ClassID, SectionName, AcademicYear, IsActive, Capacity, AllowedGender)
SELECT c.ClassID, v.SectionName, y.AcademicYear, 1, 30, N'مختلط'
FROM dbo.Classes c
CROSS JOIN dbo.AcademicYears y
CROSS JOIN (VALUES (N'Section A'), (N'Section B'), (N'Section C'), (N'Section D')) v(SectionName)
WHERE c.IsActive = 1 AND y.IsActive = 1
  AND NOT EXISTS
  (
      SELECT 1 FROM dbo.SchoolSections ss
      WHERE ss.ClassID = c.ClassID AND ss.AcademicYear = y.AcademicYear AND ss.SectionName = v.SectionName
  );
GO


INSERT dbo.SchoolSettings (SchoolSettingsID, SchoolNameAr, SchoolNameEn)
SELECT 1, N'اسم المدرسة', N'School Name'
WHERE NOT EXISTS (SELECT 1 FROM dbo.SchoolSettings WHERE SchoolSettingsID = 1);
GO

